func setGetObjectStreamingRequestValidationModeMember(input interface{}, mode string) {
	in := input.(*GetObjectStreamingInput)
	in.ChecksumMode = types.ChecksumMode(mode)
}

func addGetObjectStreamingOutputChecksumMiddlewares(stack *middleware.Stack, options Options) error {
	return internalChecksum.AddOutputMiddleware(stack, internalChecksum.OutputMiddlewareOptions{
		GetValidationMode:             getGetObjectStreamingRequestValidationModeMember,
		SetValidationMode:             setGetObjectStreamingRequestValidationModeMember,
		ResponseChecksumValidation:    options.ResponseChecksumValidation,
		ValidationAlgorithms:          []string{"CRC64NVME", "CRC32", "CRC32C", "SHA256", "SHA1"},
		IgnoreMultipartValidation:     false,
		LogValidationSkipped:          !options.DisableLogOutputChecksumValidationSkipped,
		LogMultipartValidationSkipped: !options.DisableLogOutputChecksumValidationSkipped,
	})
}
